{
  "headline": "Haloperidol lactate is not on FDA's shortage list as of 2026-10-21; Corvale East has 5.3 days of 5 mg/mL 1 mL vials on hand",
  "headline_cites": ["D7", "D1"],
  "sentences": [
    {
      "text": "FDA's records show haloperidol lactate is not on the drug shortage list as of 2026-10-21.",
      "cites": ["D7"]
    },
    {
      "text": "Corvale East holds 40 vials of the 5 mg/mL 1 mL presentation with 7.6 vials used per day, giving 5.3 days on hand.",
      "cites": ["D1"]
    },
    {
      "text": "Corvale General holds 140 vials of the same presentation with 7.8 vials used per day, giving 17.9 days on hand.",
      "cites": ["D2"]
    },
    {
      "text": "Corvale Lakeside holds 31 vials with 2 vials used per day, giving 15.7 days on hand.",
      "cites": ["D3"]
    },
    {
      "text": "The rule ranks transferring 30 vials from Corvale General to Corvale East as the best option; Corvale General can spare 30 vials while keeping two weeks of supply and Corvale East would reach 9 days.",
      "cites": ["D8"]
    },
    {
      "text": "The product label for NDC 55154955305 names Fresenius Kabi USA as the manufacturing plant.",
      "cites": ["E7"]
    },
    {
      "text": "An alternate manufacturer option lists Armas Pharmaceuticals Inc., but its label names no plant we could place.",
      "cites": ["D10"]
    }
  ]
}
